-- MI-16 Night Audit and Income Audit: resumable, idempotent end-of-day control.
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_business_date(property_id UUID PRIMARY KEY REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,business_date DATE NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'OPEN',version INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ck_hospitality_business_date_status CHECK(status IN('OPEN','AUDITING','CLOSED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_night_audit_run(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,business_date DATE NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'STARTED',current_step VARCHAR(40),started_by UUID NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,finalized_by UUID,step_up_reference VARCHAR(180),idempotency_key VARCHAR(128) NOT NULL UNIQUE,version INTEGER NOT NULL DEFAULT 1,CONSTRAINT ck_hospitality_night_run_status CHECK(status IN('STARTED','BLOCKED','READY','COMPLETED','FAILED')),UNIQUE(property_id,business_date));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_night_audit_step(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_night_audit_run(id) ON DELETE RESTRICT,step_code VARCHAR(40) NOT NULL,status VARCHAR(16) NOT NULL,result JSONB NOT NULL DEFAULT '{}'::jsonb,attempt INTEGER NOT NULL DEFAULT 1,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,idempotency_key VARCHAR(180) NOT NULL UNIQUE,CONSTRAINT ck_hospitality_night_step_status CHECK(status IN('RUNNING','PASSED','BLOCKED','FAILED')),UNIQUE(run_id,step_code));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_night_audit_exception(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_night_audit_run(id) ON DELETE RESTRICT,rule_code VARCHAR(64) NOT NULL,severity VARCHAR(12) NOT NULL,entity_type VARCHAR(40),entity_id UUID,message TEXT NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'OPEN',resolved_by UUID,resolution TEXT,resolved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ck_hospitality_night_exception_status CHECK(status IN('OPEN','RESOLVED','WAIVED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_night_audit_snapshot(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_night_audit_run(id) ON DELETE RESTRICT,snapshot_type VARCHAR(32) NOT NULL,payload JSONB NOT NULL,document_hash CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(run_id,snapshot_type));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_income_audit_review(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL UNIQUE REFERENCES "{{TENANT_SCHEMA}}".hospitality_night_audit_run(id) ON DELETE RESTRICT,status VARCHAR(12) NOT NULL DEFAULT 'PENDING',notes TEXT,reviewed_by UUID,reviewed_at TIMESTAMPTZ,CONSTRAINT ck_hospitality_income_review_status CHECK(status IN('PENDING','APPROVED','REJECTED')));
CREATE INDEX IF NOT EXISTS ix_hospitality_night_exception_open ON "{{TENANT_SCHEMA}}".hospitality_night_audit_exception(run_id,status,severity);
